  );
}

/* ── Lightbox ────────────────────────────────────────────────── */
function Lightbox({ item, onClose, onPrev, onNext }) {
  /* Close on Escape, navigate with arrow keys */
  const handleKey = useCallback((e) => {
    if (e.key === 'Escape') onClose();
    if (e.key === 'ArrowLeft')  onPrev();
    if (e.key === 'ArrowRight') onNext();
  }, [onClose, onPrev, onNext]);

  useEffect(() => {
    document.addEventListener('keydown', handleKey);
    document.body.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', handleKey);
      document.body.style.overflow = '';
    };
  }, [handleKey]);

  if (!item) return null;

  return (
    <div
      className="lightbox"
      role="dialog"
      aria-modal="true"
      aria-label={`Lightbox: ${item.title}`}
      onClick={onClose}
    >
      <button
        className="lightbox__close"
        onClick={onClose}
        aria-label="Close lightbox"
      >
        ✕
      </button>
      <button
        className="lightbox__nav lightbox__nav--prev"
        onClick={(e) => { e.stopPropagation(); onPrev(); }}
        aria-label="Previous image"
      >
        ‹
      </button>
      <div
        className="lightbox__card"
        onClick={(e) => e.stopPropagation()}
        style={{ background: item.bg }}
      >
        <div className="lightbox__visual">
          <span className="lightbox__emoji" aria-hidden="true">{item.emoji}</span>
        </div>
        <div className="lightbox__info">
          <p className="lightbox__category">{item.category}</p>
          <h2 className="lightbox__title">{item.title}</h2>
          <p className="lightbox__desc">{item.desc}</p>
        </div>
      </div>
      <button
        className="lightbox__nav lightbox__nav--next"
        onClick={(e) => { e.stopPropagation(); onNext(); }}
        aria-label="Next image"
      >
        ›
      </button>
    </div>
  );
}

